    "questionText": "Q9 (2024 CSE GS-I). With reference to the Standing Deposit Facility (SDF) operationalized by the Reserve Bank of India, consider the following statements:",
    "questionEn": "Q9 (2024 CSE GS-I). With reference to the Standing Deposit Facility (SDF) operationalized by the Reserve Bank of India, consider the following statements:",
    "questionHi": "प्रश्न 9 (2024 सिविल सेवा प्रारंभिक परीक्षा)। भारतीय रिजर्व बैंक (RBI) द्वारा संचालित स्थायी जमा सुविधा (Standing Deposit Facility - SDF) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:",
