    "statements": [
      {
        "id": 1,
        "text": "The question of disqualification under the Tenth Schedule is decided by the Presiding Officer of the House."
      },
      {
        "id": 2,
        "text": "The decision of the Presiding Officer is subject to judicial review as per the Kihoto Hollohan case (1992)."
      },
      {
        "id": 3,
        "text": "The law specifies a mandatory six-month time limit within which the Presiding Officer must decide a defection petition."
      }
    ],
    "statementsHi": [
      {
        "id": 1,
        "text": "दसवीं अनुसूची के तहत अयोग्यता के प्रश्न का निर्णय सदन के पीठासीन अधिकारी द्वारा किया जाता है।"
      },
      {
        "id": 2,
        "text": "किहोतो होलोहन मामले (1992) के अनुसार पीठासीन अधिकारी का निर्णय न्यायिक समीक्षा के अधीन है।"
      },
      {
        "id": 3,
        "text": "कानून में छह महीने की अनिवार्य समय सीमा निर्दिष्ट की गई है जिसके भीतर पीठासीन अधिकारी को दलबदल याचिका पर फैसला करना होगा।"
      }
    ]
