    "officialPaperUrl": "https://www.upsc.gov.in/sites/default/files/QP-CSP-24-GENERAL-STUDIES-PAPER-I-180624.pdf",
    "sourceVerificationStatus": "OFFICIAL_VERIFIED",
    "answerVerificationStatus": "OFFICIAL_VERIFIED",
    "verificationStatus": "OFFICIAL_VERIFIED",
    "statements": [
      {
        "id": 1,
        "text": "Cas9 is a specialized endonuclease enzyme that acts as molecular scissors to cut double-stranded DNA at target locations."
      },
      {
        "id": 2,
        "text": "A synthetic guide RNA (gRNA) directs the Cas9 protein to the specific genomic sequence to be modified."
      },
      {
        "id": 3,
        "text": "CRISPR technology can only be applied to prokaryotic organisms and cannot modify eukaryotic human cells."
      }
    ],
    "statementsHi": [
      {
        "id": 1,
        "text": "Cas9 एक विशेष एंडोन्यूक्लिएज एंजाइम है जो लक्षित स्थानों पर डबल-स्ट्रैंडेड डीएनए को काटने के लिए आणविक कैंची के रूप में कार्य करता है।"
      },
      {
        "id": 2,
        "text": "एक सिंथेटिक गाइड आरएनए (gRNA) Cas9 प्रोटीन को संशोधित किए जाने वाले विशिष्ट जीनोमिक अनुक्रम तक निर्देशित करता है।"
      },
      {
        "id": 3,
        "text": "CRISPR तकनीक केवल प्रोकैरियोटिक जीवों पर लागू की जा सकती है और यूकेरियोटिक मानव कोशिकाओं को संशोधित नहीं कर सकती है।"
      }
    ]
