    "questionHi": "प्रश्न 29 (2024 सिविल सेवा प्रारंभिक परीक्षा)। भारतीय रिजर्व बैंक (RBI) द्वारा संचालित स्थायी जमा सुविधा (Standing Deposit Facility - SDF) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:",
