    "questionHi": "प्रश्न 32 (2024 सिविल सेवा प्रारंभिक परीक्षा)। CRISPR-Cas9 जीन-संपादन तकनीक के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:",
