    "questionEn": "Q52 (2024 CSE GS-I). With reference to the CRISPR-Cas9 gene editing technology, consider the following statements:",
    "questionHi": "प्रश्न 52 (2024 सिविल सेवा प्रारंभिक परीक्षा)। CRISPR-Cas9 जीन-संपादन तकनीक के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:",
