    "solution": "Correct Answer: Option (C).\n\nBoth statements are correct:\n1. SDF (introduced under Section 17 of RBI Act in April 2022) is an uncollateralized monetary policy instrument allowing RBI to absorb surplus funds from banks without pledging government securities.\n2. SDF is set 25 bps below the policy repo rate, replacing reverse repo as the operative floor of the LAF corridor.",
