    "solution": "Correct Answer: Option (A).\n\nStatements 1 and 2 are correct. Statement 3 is incorrect because the Tenth Schedule does not specify any statutory time limit for the Speaker/Chairman to decide defection cases (though the Supreme Court in Keisham Meghachandra Singh case 2020 recommended a 3-month outer limit).",
