    "questionType": "STATEMENT_BASED",
    "questionText": "Q94 (2024 CSE GS-I). With reference to the Standing Deposit Facility (SDF) operationalized by the Reserve Bank of India, consider the following statements:",
    "questionEn": "Q94 (2024 CSE GS-I). With reference to the Standing Deposit Facility (SDF) operationalized by the Reserve Bank of India, consider the following statements:",
    "questionHi": "प्रश्न 94 (2024 सिविल सेवा प्रारंभिक परीक्षा)। भारतीय रिजर्व बैंक (RBI) द्वारा संचालित स्थायी जमा सुविधा (Standing Deposit Facility - SDF) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:",
    "options": [
      {
        "id": "A",
        "text": "1 only"
      },
      {
        "id": "B",
        "text": "2 only"
      },
      {
        "id": "C",
        "text": "Both 1 and 2"
      },
      {
        "id": "D",
        "text": "Neither 1 nor 2"
      }
    ],
    "optionsEn": [
      {
        "id": "A",
        "text": "1 only"
      },
      {
        "id": "B",
        "text": "2 only"
      },
      {
        "id": "C",
        "text": "Both 1 and 2"
      },
      {
        "id": "D",
        "text": "Neither 1 nor 2"
      }
    ],
    "optionsHi": [
      {
        "id": "A",
        "text": "केवल 1"
      },
      {
        "id": "B",
        "text": "केवल 2"
      },
      {
        "id": "C",
        "text": "1 और 2 दोनों"
      },
      {
        "id": "D",
        "text": "न तो 1, न ही 2"
      }
    ],
    "officialAnswer": "C",
    "officialAnswerSource": "UPSC Civil Services (GS Paper I) 2024 Official Master Answer Key",
    "solution": "Correct Answer: Option (C).\n\nBoth statements are correct:\n1. SDF (introduced under Section 17 of RBI Act in April 2022) is an uncollateralized monetary policy instrument allowing RBI to absorb surplus funds from banks without pledging government securities.\n2. SDF is set 25 bps below the policy repo rate, replacing reverse repo as the operative floor of the LAF corridor.",
    "solutionSource": "IKSHOVIA Commission Editorial & Verified Reference Standard",
    "topic": "Monetary Policy & Liquidity Management",
    "subject": "Economic & Social Development",
    "subjectId": "sub_economy",
    "gsPaper": "GS Paper III",
    "prelimsArea": "Macroeconomics, Banking & Schemes",
    "difficulty": "HARD",
    "sourcePage": "Official Question Booklet Page 24",
    "sourcePageNumber": 24,
    "officialPaperUrl": "https://www.upsc.gov.in/sites/default/files/QP-CSP-24-GENERAL-STUDIES-PAPER-I-180624.pdf",
    "sourceVerificationStatus": "OFFICIAL_VERIFIED",
    "answerVerificationStatus": "OFFICIAL_VERIFIED",
    "verificationStatus": "OFFICIAL_VERIFIED",
    "statements": [
      {
        "id": 1,
        "text": "It enables the RBI to absorb surplus liquidity from commercial banks without offering government collateral in return."
      },
      {
        "id": 2,
        "text": "It replaced the fixed-rate reverse repo as the floor of the Liquidity Adjustment Facility (LAF) corridor."
      }
    ],
    "statementsHi": [
      {
        "id": 1,
        "text": "यह RBI को बदले में सरकारी प्रतिभूति (कोलेटरल) दिए बिना वाणिज्यिक बैंकों से अतिरिक्त तरलता को अवशोषित करने में सक्षम बनाता है।"
      },
      {
        "id": 2,
        "text": "इसने तरलता समायोजन सुविधा (LAF) कॉरिडोर के निचले स्तर (floor) के रूप में फिक्स्ड-रेट रिवर्स रेपो को प्रतिस्थापित किया है।"
      }
    ]
